      "path": "src/server/http/catalog.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 目录代理路由：目录/统计载荷的服务端缓存，以及与安装/任务模块共享的 profile 级已装包读取。\n */\nimport { mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { dirname, join } from 'node:path'\nimport { githubRepoOf } from '../services/install/install.ts'\nimport { loadSettings } from '../services/settings.ts'\nimport { fetchViaCurl, systemProxy } from '../services/probe.ts'\nimport { CATALOG_CACHE_TTL_MS, requireMethod, sendJson, type WebRoute, type WebServerService } from './shared.ts'\n\n/** 磁盘缓存内容：原始响应字符串 + 写入时间戳（TTL 判定用）。 */\ninterface CatalogCacheEntry {\n  at: number\n  body: string\n}\n\nfunction catalogCacheFile(profile: string, key: string): string {\n  return join(profileDirectory(profile), 'cache', `catalog-${key}.json`)\n}\n\n/** 目录拉取超时：目录 JSON 约 3.6MB，20s 在弱网/代理链路上不够用；\n *  客户端会在超时后重试，重试必须共享同一次拉取（见 fetchCatalogOnce）。 */\nconst CATALOG_FETCH_TIMEOUT_MS = 60_000\n\n/** 并发拉取去重：客户端超时重试会并发打进来，共享同一次 curl，\n *  避免多份 3.6MB 下载互相抢带宽、越重试越慢。 */\nconst inflightCatalog = new Map<string, ReturnType<typeof fetchViaCurl>>()\n\nfunction fetchCatalogOnce(target: string, proxy: string): ReturnType<typeof fetchViaCurl> {\n  const key = `${target}\\n${proxy}`\n  const running = inflightCatalog.get(key)\n  if (running !== undefined) return running\n  const task = fetchViaCurl(target, proxy, CATALOG_FETCH_TIMEOUT_MS)\n    .finally(() => { inflightCatalog.delete(key) })\n  inflightCatalog.set(key, task)\n  return task\n}\n\n/** 读缓存：文件存在、JSON 合法、未超过 maxAgeMs → 返回原始响应字符串；否则 null（视为 miss）。\n *  maxAgeMs 传 Infinity 即「任意年龄的缓存」，供实时拉取失败时兜底使用。 */\nfunction readCatalogCache(file: string, maxAgeMs: number): string | null {\n  try {\n    const entry = JSON.parse(readFileSync(file, 'utf8')) as CatalogCacheEntry\n    if (entry && typeof entry.at === 'number' && typeof entry.body === 'string'\n      && Date.now() - entry.at < maxAgeMs) {\n      return entry.body\n    }\n  } catch {\n    // 文件缺失 / 解析失败 / 字段不完整 → miss，重新拉取覆盖写盘\n  }\n  return null\n}\n\n/** 写缓存：目录不存在则创建；写失败静默忽略（缓存只是加速，不影响功能）。 */\nfunction writeCatalogCache(file: string, body: string): void {\n  try {\n    mkdirSync(dirname(file), { recursive: true })\n    writeFileSync(file, JSON.stringify({ at: Date.now(), body } satisfies CatalogCacheEntry))\n  } catch {\n    // 磁盘只读/无权限等极端情况：忽略，继续走直连\n  }\n}\n\nexport function profileDirectory(profile: string): string {\n  return join(process.env.DSH_HOME ?? join(homedir(), '.dsh'), 'profiles', profile)\n}\n\n/** 读取安装进某 profile 的非官方依赖。 */\nexport function readInstalled(profile: string): Record<string, string> {\n  try {\n    const manifest = JSON.parse(readFileSync(join(profileDirectory(profile), 'package.json'), 'utf8')) as {\n      dependencies?: Record<string, string>\n    }\n    return Object.fromEntries(\n      Object.entries(manifest.dependencies ?? {}).filter(([name]) => !name.startsWith('@deepseek-ai/')),\n    )\n  } catch {\n    return {}\n  }\n}\n\n/** 读已装依赖实际落在磁盘上的仓库身份（`owner/repo`）：解析 node_modules/<name>/package.json\n *  的 repository 字段。已装 spec 可能是纯版本号（丢了仓库身份），但真实包元数据仍指向来源仓库，\n *  据此可区分「同名依赖其实是同一仓库的残留（应转 update）」还是「跨仓库包名冲突（应报错）」。\n *  读不到 / 解析不出返回 null（交给调用方按冲突处理）。 */\nexport function installedRepoOf(profile: string, name: string): string | null {\n  try {\n    const pkg = JSON.parse(readFileSync(join(profileDirectory(profile), 'node_modules', name, 'package.json'), 'utf8')) as {\n      repository?: string | { url?: string }\n    }\n    const repo = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url\n    return repo ? githubRepoOf(repo) : null\n  } catch {\n    return null\n  }\n}\n\nexport function registerCatalogRoutes(webServer: WebServerService, profile: string): WebRoute[] {\n  return [\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/catalog',\n      handler: async (request, response) => {\n        if (!requireMethod(request, response, 'GET')) return\n        // 目录/统计数据服务端代理：浏览器不直连 dsh-plugin.org，统一经此路由\n        // 转发（curl 子进程注入代理 env），与 npm / git 安装通道走同一代理口径，\n        // 「npm / git / 目录数据请求统一走该代理」的设置文案因此真实生效。\n        const url = new URL(request.url ?? '/', 'http://localhost')\n        const settings = loadSettings(profile)\n        // 代理优先级与安装/诊断一致：设置里的代理 → 系统代理 → 环境变量 → 直连\n        const proxy = settings.proxy !== ''\n          ? settings.proxy\n          : (systemProxy() ?? process.env.HTTPS_PROXY ?? process.env.https_proxy ?? '')\n        const isStats = url.searchParams.get('stats') === '1'\n        const lang = url.searchParams.get('lang') === 'en' ? 'en' : 'zh'\n        const target = isStats\n          ? 'https://api.dsh-plugin.org/stats.json'\n          : `https://api.dsh-plugin.org/plugins.${lang}.json`\n        // 1 小时本地缓存：命中直接返回（跨重启生效，插件市场秒开），未命中才走 curl 拉远程。\n        // refresh=1 跳过 TTL 缓存直接回源（「强制刷新」用）；成功后照样覆盖缓存，\n        // 失败仍回退旧缓存，所以强制刷新不会把可用的旧数据弄丢。\n        const cacheFile = catalogCacheFile(profile, isStats ? 'stats' : `plugins-${lang}`)\n        const forceRefresh = url.searchParams.get('refresh') === '1'\n        const cached = forceRefresh ? null : readCatalogCache(cacheFile, CATALOG_CACHE_TTL_MS)\n        if (cached !== null) {\n          try {\n            sendJson(response, 200, JSON.parse(cached))\n            return\n          } catch {\n            // 缓存正文损坏：忽略，走重新拉取并覆盖写盘\n          }\n        }\n        const r = await fetchCatalogOnce(target, proxy)\n        if (!r.ok || r.body === '') {\n          // 实时拉取失败：退回任意年龄的本地缓存（上次成功数据），\n          // 避免证书吊销受阻 / 网络抖动时整个插件市场打不开 —— 数据可能过期，但好过空白。\n          const stale = readCatalogCache(cacheFile, Number.POSITIVE_INFINITY)\n          if (stale !== null) {\n            try {\n              sendJson(response, 200, JSON.parse(stale))\n              return\n            } catch {\n              // 兜底缓存也损坏：落到下面的 502\n            }\n          }\n          sendJson(response, 502, { error: 'catalog fetch failed' })\n          return\n        }\n        try {\n          sendJson(response, 200, JSON.parse(r.body))\n          writeCatalogCache(cacheFile, r.body)\n        } catch {\n          sendJson(response, 502, { error: 'catalog fetch returned invalid JSON' })\n        }\n      },\n    },\n  ]\n}\n"
    },
    {
      "path": "src/client/hooks/useTaskQueue.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 插件中心的后台安装/卸载任务队列。\n *\n * 通过轮询 /active 镜像服务端 FIFO 活动队列，对消失的任务用 /status 收尾，并暴露\n * 队列动作（安装、卸载、取消）以及弹窗用的任务查找。\n */\nimport { useEffect, useRef, useState } from 'react'\nimport type { HubPlugin, InstallChannel, LocaleId, Translate } from '../types.ts'\nimport { executedCommandOf, installCommandOf, installTargetOf, repoFromInstallTarget } from '../logic/install-command.ts'\nimport type { InstalledItem } from '../logic/installed.ts'\n\n/** 安装/卸载请求超时（ms）：服务端入队前要做目录包校验与网络探测（各自有超时，合计可达十几秒），\n *  给足余量；超时主动中止，避免服务端网络挂起时前端永久卡「安装中 0%」。 */\nconst REQUEST_TIMEOUT_MS = 60_000\n\n/** 客户端任务队列项：镜像服务端 active 任务（running 在前、pending 在后）。 */\nexport interface QueueTask {\n  id: number\n  kind: 'install' | 'uninstall'\n  /** 展示目标：owner/repo（安装）或 npm 包名（卸载） */\n  target: string\n  /** 插件中文简介（入队时从插件数据带过来，轮询合并时保留）：展示在仓库名下方，标识排队中的插件 */\n  desc?: string\n  /** 所属插件仓库（owner/repo）：失败时错误弹窗据此提供「去仓库反馈」入口；卸载为 null */\n  repo: string | null\n  /** 自定义安装入口渠道（NPM 包卡片）：失败时错误/通知精准溯源「从哪个入口发起」；\n   *  目录插件安装无此字段（非自定义入口）。 */\n  channel?: InstallChannel\n  /** 实际动作（add/update/remove）：成功通知据此区分「安装成功」与「更新成功」。\n   *  服务端 /active 带回真实动作；本地乐观入队按 update 标记推断。 */\n  action?: 'add' | 'update' | 'remove'\n  /** 安装时的目录信号快照（版本 + 仓库更新时间）：任务成功后在本地记录，供「有更新」比对 */\n  version?: string\n  updatedAt?: string\n  /** 服务端在成功终态带出的**实际**安装版本（读 profile 的 node_modules）：优先于目录版本写账本 */\n  installedVersion?: string\n  /** pending 排队中 / running 执行中 / cancelling 取消中（客户端乐观过渡态） */\n  status: 'pending' | 'running' | 'cancelling'\n  progress: number\n  lines: string[]\n  /** 乐观入队条目：点击安装后立即显示「正在安装中」，等 POST 响应回来再换成真实任务 id。\n   *  服务端还没登记，轮询合并/消失检测都必须跳过，避免被当作已结束任务收尾。 */\n  optimistic?: boolean\n  /** 实际执行的安装命令（随插件数据决定）：失败时 issue 预填如实展示 */\n  command?: string\n  /** 实际执行/重试过的安装命令（按先后顺序）：失败时 issue 预填一并贴给作者 */\n  attempts?: string[]\n  /** 完成结果是否需要重启才生效（服务端任务终态带出）。默认 true 保底：数据缺失时不静默视为已生效。\n   *  仅刷新解决不了的兜底场景（热挂载失败 / 非 dsh 插件 / 更新）为 true，结果视图给「立即重启」；\n   *  其余（热挂载成功、卸载已即时停用、全局安装）为 false，结果视图仅「完成」。 */\n  needsRestart: boolean\n  /** 完成结果是否只需刷新页面即生效（插件已热挂进运行中 loader，或卸载后插件面板仍残留在当前页面）：\n   *  true 时关闭结果弹窗 / Toast 消失后由上层自动刷新页面，不给手动刷新按钮。 */\n  needsReload?: boolean\n  /** 市场自更新成功、但 profile 的 bundle 列表里已不含 dsh-plugin：重启后市场不会出现 */\n  bundleDeselected?: boolean\n}\n\n/** 客户端待重启项：镜像服务端内存列表 + 本地补齐的展示信息（简介/版本）。 */\nexport interface PendingRestart {\n  /** owner/repo（展示用，已从安装目标归一化） */\n  target: string\n  /** 待重启语义：install 装完等挂载 / uninstall 卸完等清理 */\n  kind: 'install' | 'uninstall'\n  at: number\n  desc?: string\n  version?: string\n}\n\nexport interface TaskQueueOptions {\n  t: Translate\n  /** 界面语言（zh/en）：随安装请求带给服务端，安装前网络探测等错误消息按用户语言提示 */\n  langKey?: LocaleId\n  refreshInstalled: () => void\n  /** 任务成功完成：viaModal 表示任务对应当前打开弹窗（弹窗切结果视图），否则走 Toast；repo 供成功通知记录；\n   *  needsRestart 表示该任务完成后是否仍需宿主重启（结果视图据此给「重启 / 仅完成」）；\n   *  needsReload 表示是否只需刷新页面即生效（热挂载成功、或卸载后插件面板仍残留）。\n   *  update 表示实际执行的是更新（覆盖重装）而非首次安装：通知中心据此显示「更新成功」而非「安装成功」。 */\n  onInstallDone: (viaModal: boolean, repo: string | null, needsRestart: boolean, update?: boolean, needsReload?: boolean, bundleDeselected?: boolean) => void\n  onUninstallDone: (viaModal: boolean, repo: string | null, needsRestart: boolean, needsReload?: boolean) => void\n  /** 任务失败：完整输出或兜底文案 + 所属插件仓库 + 操作类型（安装/卸载）+ 实际执行的安装命令（issue 预填用，可缺省）+ 实际执行/重试过的安装命令（可缺省）+ 是否更新。 */\n  onError: (message: string, repo: string | null, kind: 'install' | 'uninstall', command?: string, attempts?: string[], update?: boolean) => void\n  /** 当前打开的安装/卸载弹窗插件：用于在弹窗内匹配进行中的任务。 */\n  installPlugin: HubPlugin | null\n  /** 当前打开的自定义安装（命令行）确认弹窗目标：与应用商店同一弹窗机制，匹配进行中的 custom 安装任务。 */\n  installCustomTarget?: string | null\n  /** 当前打开的全局 npm 安装（`npm install -g <pkgs>`）确认弹窗身份（包列表空格拼接）：\n   *  匹配服务端登记的全局安装任务（target = 包列表 join(' ')）。 */\n  installGlobalTarget?: string | null\n  uninstallPlugin: HubPlugin | null\n  /** 已安装视图发起的卸载目标（npm 包名）：目录插件走 uninstallPlugin，自定义安装走包名直卸。 */\n  uninstallName: string | null\n  installedName: (p: HubPlugin) => string | null\n  /** 待重启项展示信息补齐：按 owner/repo 从插件目录解析简介/版本；找不到返回 null。 */\n  resolvePending: (repo: string) => { desc?: string; version?: string } | null\n}\n\n/** 失败消息的入口溯源前缀：自定义安装（带渠道）在错误正文顶部精准指出从哪张卡片发起；\n *  目录插件安装（无渠道）返回 null，错误正文保持原样。 */\nconst entryLineOf = (t: Translate, channel: InstallChannel | undefined): string | null =>\n  channel ? t('installEntryLine', { c: t('installChannelNpm') }) : null\n\nexport function useTaskQueue(opts: TaskQueueOptions) {\n  const {\n    t, langKey, refreshInstalled, onInstallDone, onUninstallDone, onError,\n    installPlugin, installCustomTarget, installGlobalTarget, uninstallPlugin, uninstallName, installedName, resolvePending,\n  } = opts\n  const [queue, setQueue] = useState<QueueTask[]>([])\n  const queueRef = useRef<QueueTask[]>([])\n  /** 待重启列表（服务端内存态 + 本地展示信息补齐）；与 queue 一样以 ref 为唯一事实来源。 */\n  const [pendingRestarts, setPendingRestarts] = useState<PendingRestart[]>([])\n  const pendingRef = useRef<PendingRestart[]>([])\n  /** 本次会话内安装成功插件的展示信息（目标 → 简介/版本）：轮询合并待重启列表时补齐，刷新后由 resolvePending 兜底。 */\n  const pendingInfoRef = useRef<Map<string, { desc?: string; version?: string }>>(new Map())\n  /** 保持最新的 resolvePending：轮询闭包捕获的是调用那一刻的目录状态，目录晚加载时也能补齐。 */\n  const resolvePendingRef = useRef(resolvePending)\n  resolvePendingRef.current = resolvePending\n  /** 当前打开弹窗所对应的任务 id：该任务完成时弹窗切换为结果视图 */\n  const modalTaskRef = useRef<number | null>(null)\n  /** 已开始收尾但尚未结束的任务 id（服务端 /active 已消失 → 查 /status 中）：并发轮询时跳过，避免重复收尾 */\n  const settlingRef = useRef<Set<number>>(new Set())\n  /** 轮询定时器句柄（队列清空/组件卸载时清理） */\n  const pollRef = useRef<number | null>(null)\n  /** 请求在途的目标集合（同步防重）：双击安装/卸载时第二击直接忽略。\n   *  本地队列任务要等 fetch 返回后才入队，仅靠 queueRef 检查拦不住请求窗口内的重复点击。 */\n  const submittingRef = useRef<Set<string>>(new Set())\n  /** 乐观入队临时 id 计数器：递减产生唯一负数，与服务端自增正数 id 永不冲突。 */\n  const tempIdRef = useRef(0)\n  /** 请求在途标记：弹窗据此禁用确认按钮，避免等待响应期间被再次点击。 */\n  const [submitting, setSubmitting] = useState(false)\n\n  /** 停止后台任务轮询（任务结束或组件卸载时清理）。 */\n  const stopPoll = () => {\n    if (pollRef.current !== null) {\n      window.clearInterval(pollRef.current)\n      pollRef.current = null\n    }\n  }\n\n  /** 队列与待重启都清空才停轮询：待重启期间持续轮询，宿主一重启（内存列表清空）立刻感知并消失。 */\n  const maybeStopPoll = () => {\n    if (queueRef.current.length === 0 && pendingRef.current.length === 0) stopPoll()\n  }\n\n  // 组件卸载时兜底清理轮询定时器\n  useEffect(() => stopPoll, [])\n\n  /** 更新队列（同步镜像到 ref：queueRef 是唯一事实来源，state 只负责触发渲染，\n   *  避免依赖 React updater 的异步调度时序导致 gone/stopPoll/防重复入队读到旧值）。 */\n  const applyQueue = (updater: (prev: QueueTask[]) => QueueTask[]) => {\n    const next = updater(queueRef.current)\n    queueRef.current = next\n    setQueue(next)\n  }\n\n  /** 解析服务端待重启列表（安装目标归一化为 owner/repo，与安装任务对齐）。 */\n  const parsePendingRestarts = (value: unknown): PendingRestart[] => {\n    if (!Array.isArray(value)) return []\n    const out: PendingRestart[] = []\n    for (const x of value) {\n      if (typeof x !== 'object' || x === null) continue\n      const target = (x as { target?: unknown }).target\n      if (typeof target !== 'string' || target === '') continue\n      const at = (x as { at?: unknown }).at\n      out.push({\n        target: repoFromInstallTarget(target),\n        kind: (x as { kind?: unknown }).kind === 'uninstall' ? 'uninstall' : 'install',\n        at: typeof at === 'number' ? at : 0,\n      })\n    }\n    return out\n  }\n\n  /** 合并服务端待重启列表：保留已有展示信息，缺失时用会话内记录 / 目录解析补齐。 */\n  const applyPending = (raw: PendingRestart[]) => {\n    const prev = pendingRef.current\n    const next = raw.map((p) => {\n      const old = prev.find((q) => q.target === p.target)\n      if (old?.desc !== undefined) return { ...p, desc: old.desc, version: old.version }\n      const info = pendingInfoRef.current.get(p.target) ?? resolvePendingRef.current?.(p.target) ?? null\n      return info ? { ...p, desc: info.desc, version: info.version } : p\n    })\n    pendingRef.current = next\n    setPendingRestarts(next)\n  }\n\n  /** 向宿主记录某插件的安装时目录信号（version + updatedAt）。\n   *  版本未知时**不写**：服务端把空版本当作「卸载清理」会删掉整条记录（连 npm 包名映射一起），\n   *  刷新页面后任务丢了快照就会走到这条路径 —— 宁可保留旧记录，也不能把账本清空。 */\n  const syncInstalledVersion = async (repo: string | null, version: string | undefined, updatedAt: string | undefined) => {\n    if (!repo || version === undefined || version === '') return\n    try {\n      await fetch('/dsh-plugin-hub/installed-version', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ repo, version, updatedAt }),\n      })\n    } catch {\n      // 宿主未挂本地路由：静默忽略，仅本机展示受影响\n    }\n  }\n\n  /** 清除某仓库的版本记录（卸载成功后调用）：空版本是服务端的「删除记录」语义，只在这里显式发送。 */\n  const clearInstalledVersion = async (repo: string | null) => {\n    if (!repo) return\n    try {\n      await fetch('/dsh-plugin-hub/installed-version', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ repo, version: null }),\n      })\n    } catch {\n      // 同上：清理失败不影响卸载结果\n    }\n  }\n\n  /** 后台任务结束（active 中消失后查终态确认）：完成 → 刷新安装表 + 结果视图/toast；失败 → 完整错误弹窗 */\n  const finishQueueTask = (ok: boolean, q: QueueTask, lines: string[]) => {\n    applyQueue((prev) => prev.filter((x) => x.id !== q.id))\n    if (ok) {\n      refreshInstalled()\n      if (q.kind === 'uninstall') {\n        // 卸载成功：清掉本地版本记录\n        void clearInstalledVersion(q.repo)\n        onUninstallDone(modalTaskRef.current === q.id, q.repo, q.needsRestart, q.needsReload ?? false)\n      } else {\n        // 安装成功：记录安装时的目录信号（版本 + 仓库更新时间），供「有更新」比对；\n        // 同时缓存展示信息，待重启列表（服务端已登记）合并时直接补齐简介/版本\n        // 账本记**实际装上的版本**：目录版本可能滞后，抄目录字段会让「有更新」永久失真\n        const recordedVersion = q.installedVersion ?? q.version\n        void syncInstalledVersion(q.repo, recordedVersion, q.updatedAt)\n        pendingInfoRef.current.set(q.target, { desc: q.desc, version: recordedVersion })\n        onInstallDone(modalTaskRef.current === q.id, q.repo, q.needsRestart, q.action === 'update', q.needsReload ?? false, q.bundleDeselected === true)\n      }\n    } else {\n      // 失败：完整展示全部输出行（最新在前，逆序为日志阅读顺序），不裁剪\n      const rawDetail = lines.length > 0\n        ? [...lines].reverse().join('\\n')\n        : q.kind === 'uninstall' ? t('uninstallFail') : t('installFail')\n      // 自定义安装（带入口渠道）：错误正文顶部精准提示「从哪张卡片发起」，目录安装保持原样\n      const entry = entryLineOf(t, q.channel)\n      onError(entry ? `${entry}\\n${rawDetail}` : rawDetail, q.repo, q.kind, executedCommandOf(q.command, q.attempts), q.attempts, q.action === 'update')\n    }\n    maybeStopPoll()\n  }\n\n  /** 卸载成功收尾前的进度过渡：任务已在服务端结束，但保留本地展示，\n   *  让进度条在 ~2.4s 内缓缓跑到 100% 再切结果/Toast，给用户一个交互过程，\n   *  而不是命令一执行进度条就一闪消失。 */\n  const settleDone = (q: QueueTask, lines: string[]) => {\n    // 收尾动画期间停止轮询：任务已从服务端 /active 消失，无需再查；\n    // 停掉可避免 pollQueue 的 gone 检测把它当「再消失一次」而重复收尾\n    stopPoll()\n    const from = Math.min(q.progress, 90) // 起点最多 90，给进度条留出跑满的缓冲空间\n    const steps = 20\n    const stepMs = 120 // 20 步 × 120ms = 2.4s\n    let step = 0\n    // 动画期间固定显示「卸载中」：任务实已结束，但进度在跑，与「排队中」文案更协调\n    applyQueue((prev) => prev.map((x) => (x.id === q.id ? { ...x, status: 'running' as const } : x)))\n    const timer = window.setInterval(() => {\n      step += 1\n      const progress = Math.round(from + (100 - from) * (step / steps))\n      applyQueue((prev) => prev.map((x) => (x.id === q.id ? { ...x, progress } : x)))\n      if (step >= steps) {\n        window.clearInterval(timer)\n        finishQueueTask(true, q, lines)\n        // 队列若还有其它已在排队/执行的任务，恢复轮询继续盯；已清空则自然停住\n        if (queueRef.current.length > 0) pollQueue()\n      }\n    }, stepMs)\n  }\n\n  /** 任务在 /active 中消失 = 已结束：查 /status 拿终态并收尾（cancelled 静默移除）。 */\n  const settleTask = async (q: QueueTask) => {\n    let status = 'failed'\n    let lines: string[] = []\n    let attempts: string[] | undefined\n    let bundleDeselected: boolean | undefined\n    let installedVersion: string | undefined\n    try {\n      const res = await fetch(`/dsh-plugin-hub/status?task=${q.id}`, { cache: 'no-store' })\n      if (res.ok) {\n        const data = await res.json() as { task?: { status?: string; lines?: string[]; attempts?: string[]; needsRestart?: unknown; needsReload?: unknown; bundleDeselected?: unknown; installedVersion?: unknown } }\n        const task = data.task\n        if (task !== undefined) {\n          status = task.status ?? 'failed'\n          lines = task.lines ?? []\n          attempts = Array.isArray(task.attempts) ? task.attempts : undefined\n          bundleDeselected = task.bundleDeselected === true ? true : undefined\n          installedVersion = typeof task.installedVersion === 'string' && task.installedVersion !== '' ? task.installedVersion : undefined\n          // 终态带出的「是否需要重启 / 是否只需刷新」覆盖本地（服务端 done 时按 loader 热挂/即时移除情况设置）\n          const needsRestart = typeof task.needsRestart === 'boolean' ? task.needsRestart : q.needsRestart\n          const needsReload = typeof task.needsReload === 'boolean' ? task.needsReload : (q.needsReload ?? false)\n          if (status === 'done') {\n            const settled = { ...q, needsRestart, needsReload, bundleDeselected: bundleDeselected === true ? true : q.bundleDeselected, installedVersion }\n            // 卸载成功走进度过渡动画；安装成功直接收尾\n            if (q.kind === 'uninstall') settleDone(settled, lines)\n            else finishQueueTask(true, settled, lines)\n            return\n          }\n          if (status === 'failed') {\n            // 服务端终态带出的尝试记录覆盖本地：以实际执行为准\n            finishQueueTask(false, { ...q, attempts }, lines)\n            return\n          }\n        }\n      }\n    } catch { /* 服务端不可达：按失败处理 */ }\n    applyQueue((prev) => prev.filter((x) => x.id !== q.id)) // cancelled / 未知\n    maybeStopPoll()\n  }\n\n  /** 轮询整个队列：合并服务端 /active（running 在前、pending 在后），\n   *  消失的任务查终态收尾；队列清空即停止轮询。 */\n  const pollQueue = () => {\n    stopPoll()\n    pollRef.current = window.setInterval(async () => {\n      try {\n        const res = await fetch('/dsh-plugin-hub/active', { cache: 'no-store' })\n        if (!res.ok) throw new Error(`active ${res.status}`)\n        const data = await res.json() as {\n          tasks?: { id?: unknown; action?: unknown; target?: unknown; status?: unknown; progress?: unknown; lines?: unknown; attempts?: unknown; needsRestart?: unknown; installChannel?: unknown; bundleDeselected?: unknown }[]\n          pendingRestarts?: unknown\n        }\n        const active = (data.tasks ?? []).filter((a) => typeof a.id === 'number')\n        const byId = new Map(active.map((a) => [a.id as number, a]))\n        // 先捕获旧队列：gone 是「旧队列里服务端已消失的任务」的差集，必须在 applyQueue 更新前取\n        const prevQueue = queueRef.current\n        // 待重启列表同步（服务端内存态：宿主重启后自然变空，这里随之清空 UI）\n        applyPending(parsePendingRestarts(data.pendingRestarts))\n        // 合并：running 在前、pending 在后（与服务端一致），新出现任务补入队列\n          applyQueue((prev) => {\n            const next: QueueTask[] = []\n            for (const a of active) {\n              const id = a.id as number\n              const prevTask = prev.find((q) => q.id === id)\n              const isRemove = a.action === 'remove'\n              next.push({\n                id,\n                kind: isRemove ? 'uninstall' : 'install',\n                target: typeof a.target === 'string' ? repoFromInstallTarget(a.target) : (prevTask?.target ?? ''),\n                desc: prevTask?.desc,\n                repo: prevTask?.repo ?? (isRemove ? null : (typeof a.target === 'string' ? repoFromInstallTarget(a.target) : null)),\n                // 安装时快照的目录信号：轮询合并时保留，任务成功后记录到本地\n                version: prevTask?.version,\n                updatedAt: prevTask?.updatedAt,\n                status: a.status === 'running' ? 'running' : 'pending',\n                progress: typeof a.progress === 'number' ? a.progress : prevTask?.progress ?? 0,\n                lines: Array.isArray(a.lines) ? (a.lines as string[]) : (prevTask?.lines ?? []),\n                attempts: Array.isArray(a.attempts) ? (a.attempts as string[]) : (prevTask?.attempts ?? []),\n                needsRestart: typeof a.needsRestart === 'boolean' ? a.needsRestart : (prevTask?.needsRestart ?? true),\n                bundleDeselected: a.bundleDeselected === true || prevTask?.bundleDeselected === true,\n                // 入口渠道：本地乐观入队已带；服务端 /active 也带回（刷新恢复用），服务端优先。\n                // 旧服务端可能回传已废弃的 'git'/'dsh' 渠道，忽略即可、回退本地值。\n                channel: a.installChannel === 'npm' ? 'npm' : prevTask?.channel,\n              })\n            }\n            // 保留乐观条目：服务端尚未登记，无真实 id，不能因 active 缺它就被合并吞掉\n            const keepOpt = prev.filter((q) => q.optimistic && !next.some((x) => x.id === q.id))\n            if (keepOpt.length > 0) next.push(...keepOpt)\n            // 保留「已从服务端消失、但尚未收尾」的任务：收尾（settleTask）负责移除。\n            // 若在这里提前摘除，卸载/安装完成的那一瞬队列会先变空，弹窗闪回「确认」态\n            // （busy=false 且未 done），表现为「卸载中 → 卸载 → 卸载完成」的中间回退。\n            const keepGone = prev.filter((q) =>\n              !byId.has(q.id) && !next.some((x) => x.id === q.id) && q.status !== 'cancelling' && !q.optimistic)\n            if (keepGone.length > 0) next.push(...keepGone)\n            return next\n          })\n          // 本地有、服务端已消失 → 已结束：逐个查终态收尾\n          // （cancelling 是客户端乐观过渡态，交给 cancelTask 的定时移除，不在轮询里提前收敛；\n          //   optimistic 是点击后尚未登记的占位，服务端 /status 查不到，跳过免误判成失败；\n          //   settling 是上一轮已开始收尾的任务，并发轮询直接跳过，避免重复收尾）\n          const gone = prevQueue.filter((q) =>\n            !byId.has(q.id) && q.status !== 'cancelling' && !q.optimistic && !settlingRef.current.has(q.id))\n        for (const q of gone) {\n          // 防御：同 id 任务可能已被上一轮收尾移除（极端时序下轮询合并出的重复条目），跳过避免重复收尾\n          if (!queueRef.current.some((x) => x.id === q.id)) continue\n          settlingRef.current.add(q.id)\n          try { await settleTask(q) } finally { settlingRef.current.delete(q.id) }\n        }\n      } catch {\n        // 服务端暂不可达：静默等待下一轮\n      }\n    }, 600)\n  }\n\n  // 刷新后恢复任务队列与待重启列表：任务注册表在服务端内存里，只要宿主进程没重启就还在；\n  // 重新拉取 /active（数组）继续轮询，界面上显示「进行中」状态条，可展开查看实时输出。\n  useEffect(() => {\n    let cancelled = false\n    const restore = async () => {\n      try {\n        const res = await fetch('/dsh-plugin-hub/active', { cache: 'no-store' })\n        if (!res.ok) return\n        const data = await res.json() as {\n          tasks?: { id?: unknown; action?: unknown; target?: unknown; status?: unknown; progress?: unknown; lines?: unknown; attempts?: unknown; needsRestart?: unknown; displayTarget?: unknown; installChannel?: unknown }[]\n          pendingRestarts?: unknown\n        }\n        if (cancelled) return\n        // 待重启：装完没重启的持久提醒，刷新页面也要恢复\n        applyPending(parsePendingRestarts(data.pendingRestarts))\n        const items: QueueTask[] = (data.tasks ?? [])\n          .filter((a) => typeof a.id === 'number')\n          .map((a) => {\n            const isRemove = a.action === 'remove'\n            // 服务端任务的 target：显式 HTTPS Git URL（安装）/ npm 包名（npm 安装/卸载）。\n            // 恢复展示统一用 displayTarget（owner/repo，服务端固定传）：npm 安装时 target 是包名，\n            // 直接展示会让用户看到「安装方式」的内部细节，违背无感知原则；卸载保持包名（匹配已装表）。\n            const display = typeof (a as { displayTarget?: unknown }).displayTarget === 'string' ? repoFromInstallTarget((a as { displayTarget: string }).displayTarget) : ''\n            const fallback = typeof a.target === 'string' ? repoFromInstallTarget(a.target) : ''\n            return {\n              id: a.id as number,\n              kind: (isRemove ? 'uninstall' : 'install') as 'install' | 'uninstall',\n              target: isRemove ? fallback : (display || fallback),\n              repo: isRemove ? null : (display || fallback),\n              action: (a.action === 'add' || a.action === 'update' || a.action === 'remove') ? a.action : 'add',\n              status: a.status === 'running' ? 'running' : 'pending',\n              progress: typeof a.progress === 'number' ? a.progress : 0,\n              lines: Array.isArray(a.lines) ? (a.lines as string[]) : [],\n              attempts: Array.isArray((a as { attempts?: unknown }).attempts) ? ((a as { attempts: string[] }).attempts) : [],\n              needsRestart: typeof (a as { needsRestart?: unknown }).needsRestart === 'boolean' ? (a as { needsRestart: boolean }).needsRestart : true,\n              // 服务端登记的入口渠道：自定义安装刷新后也能精准溯源（目录安装无此字段）。\n              // 旧服务端可能回传已废弃的 'git'/'dsh' 渠道，忽略即可。\n              channel: a.installChannel === 'npm' ? 'npm' : undefined,\n            }\n          })\n        if (items.length > 0 || pendingRef.current.length > 0) {\n          applyQueue((prev) => [...prev, ...items.filter((n) => !prev.some((p) => p.id === n.id))])\n          // 刷新后恢复的任务同样保持折叠：摘要条提示进行中，点开才看明细/日志\n          pollQueue()\n        }\n      } catch { /* 宿主未挂本插件服务端路由 */ }\n    }\n    void restore()\n    return () => { cancelled = true }\n  }, [])\n\n  /** 弹窗动作：直接安装。请求宿主本地路由，任务进入服务端队列（FIFO），弹窗内实时显示进度。 */\n  /** 安装入队核心：目录插件（catalog，后端走目录白名单）与命令行安装（custom，\n   *  受安全开关控制）共用。队列条目一律用仓库名（repo）展示/防重，只有发给后端的\n   *  实际安装目标（target）为 npm 包名。 */\n  const submitInstall = async (input: {\n    /** 发给后端的实际安装目标：npm 包名 */\n    target: string\n    /** 队列展示与防重用的仓库名 */\n    repo: string\n    desc?: string\n    version?: string\n    updatedAt?: string\n    command: string\n    source: 'catalog' | 'custom'\n    /** 更新已安装目标（放行 add 覆盖重装） */\n    update?: boolean\n    /** 钉住精确版本（Hub 自我更新用）：最新版可能仍在 pnpm 供应链门禁内，\n     *  必须安装「已过门禁」的那个版本，不能再用 @latest。 */\n    pinVersion?: string\n    /** 全局 npm 安装包列表（`npm install -g <pkgs>`）：非空时服务端执行全局安装，不进任何 profile */\n    globalNpm?: string[]\n    /** 自定义安装入口渠道（NPM 包卡片）：随请求上报服务端落日志，\n     *  失败弹窗/通知据此精准溯源「从哪个入口发起」；目录安装不传。 */\n    channel?: InstallChannel\n  }) => {\n    // 防重复入队：同一目标已在排队/执行中则忽略\n    if (queueRef.current.some((q) => q.kind === 'install' && q.target === input.repo)) return\n    // 请求在途防重：任务要等响应回来才进本地队列，这之前再次点击（双击）直接忽略\n    if (submittingRef.current.has(input.repo)) return\n    submittingRef.current.add(input.repo)\n    // 乐观入队：点击安装立即显示「正在安装中」，不等 POST 响应。\n    // 服务端 /install 会先做校验与网络探测再入队，若等响应才入队列，\n    // 用户点完安装立刻去看任务会看不到 —— 只有刷新后 restore 才拉回来。\n    // 用负临时 id 占位，响应回来换成真实 task id；失败/出错则移除该占位。\n    tempIdRef.current -= 1\n    const tempId = tempIdRef.current\n    modalTaskRef.current = tempId\n    applyQueue((prev) => [...prev, {\n      id: tempId, kind: 'install', target: input.repo, repo: input.repo, desc: input.desc,\n      version: input.version, updatedAt: input.updatedAt,\n      status: 'running', progress: 0, lines: [], optimistic: true,\n      command: input.command,\n      channel: input.channel,\n      action: input.update ? 'update' : 'add',\n      // 服务端登记后 /active 会带回真实执行过的命令，先占位空列表\n      attempts: [], needsRestart: true,\n    }])\n    setSubmitting(true)\n    const controller = new AbortController()\n    const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS)\n    try {\n      const res = await fetch('/dsh-plugin-hub/install', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({\n          repo: input.target,\n          display: input.repo,\n          source: input.source,\n          mode: input.update ? 'update' : undefined,\n          // 钉住版本（Hub 自我更新）：服务端据此执行 `add <pkg>@<version>` 而不是 @latest\n          ...(input.pinVersion ? { version: input.pinVersion } : {}),\n          // 界面语言带给服务端：安装前网络探测等错误消息按用户当前语言返回（中文界面给中文，英文界面给英文）\n          ...(langKey ? { lang: langKey } : {}),\n          // 安装入口渠道（只可能是 npm）：服务端日志/报错提示据此溯源\n          ...(input.channel ? { installChannel: input.channel } : {}),\n          ...(input.globalNpm && input.globalNpm.length > 0 ? { globalNpm: input.globalNpm } : {}),\n        }),\n        signal: controller.signal,\n      })\n      const data = await res.json() as { ok?: boolean; task?: number; error?: string; attempts?: string[] }\n      if (!data.ok || typeof data.task !== 'number') {\n        // 请求层失败（重复安装 409 / 参数错误 / 安全开关 403 等）：移除乐观条目 + 完整错误弹窗\n        applyQueue((prev) => prev.filter((x) => x.id !== tempId))\n        // 同步 400（如安装前网络探测拦截）服务端会附上已尝试的安装方式，issue 预填一并展示；\n        // 用 || 而非 ?? ：error 为空字符串时回退 HTTP 状态，避免复制出来是空白。\n        // 自定义安装（带入口渠道）：错误正文顶部精准提示「从哪张卡片发起」\n        const entry = entryLineOf(t, input.channel)\n        const msg = data.error || `HTTP ${res.status}`\n        onError(entry ? `${entry}\\n${msg}` : msg, input.repo, 'install', input.command, data.attempts)\n        return\n      }\n      const taskId = data.task\n      modalTaskRef.current = taskId\n      // 用真实任务 id 替换乐观占位，解除 optimistic 标记（此后归正常收尾/轮询处理）\n      applyQueue((prev) => prev.map((x) => (x.id === tempId\n        ? { ...x, id: taskId, optimistic: undefined }\n        : x)))\n      // 提前缓存展示信息：安装成功后服务端登记待重启，轮询合并时不用等目录解析\n      pendingInfoRef.current.set(input.repo, { desc: input.desc, version: input.version })\n      // 摘要条常驻顶部（含实时进度），明细面板保持折叠，想看时再点开\n      pollQueue()\n    } catch (err) {\n      // 网络异常：移除乐观条目 + 兜底错误弹窗（附上底层原因，避免只剩一句笼统的「安装失败」）\n      applyQueue((prev) => prev.filter((x) => x.id !== tempId))\n      const aborted = (err as { name?: string } | null)?.name === 'AbortError'\n      // [request-timeout]：给分类器一个与界面语言无关的超时标记\n      const reason = aborted\n        ? `${t('requestTimeout')}\\n[request-timeout]`\n        : err instanceof Error && err.message ? err.message : String(err ?? '')\n      // 自定义安装（带入口渠道）：错误正文顶部精准提示「从哪张卡片发起」\n      const entry = entryLineOf(t, input.channel)\n      const msg = reason ? `${t('installFail')} — ${reason}` : t('installFail')\n      onError(entry ? `${entry}\\n${msg}` : msg, input.repo, 'install', input.command)\n    } finally {\n      window.clearTimeout(timeout)\n      submittingRef.current.delete(input.repo)\n      setSubmitting(false)\n    }\n  }\n\n  /** 目录插件安装：安装目标取目录数据的 npm 包名，走 catalog 白名单。 */\n  const installNow = async (p: HubPlugin, opts?: { update?: boolean; pinVersion?: string }) => {\n    const repo = p.source?.repo ?? ''\n    if (!repo) return\n    // 目录条目必带 npm 包名：直接用包名安装（用户无感知）。\n    const target = installTargetOf(p)\n    if (!target) return\n    await submitInstall({\n      target,\n      repo,\n      desc: p.description,\n      version: p.version,\n      updatedAt: p.dates?.repoUpdatedAt,\n      command: installCommandOf(p, true),\n      source: 'catalog',\n      update: opts?.update,\n      pinVersion: opts?.pinVersion,\n    })\n  }\n\n  /** 命令行安装：用户手输 npm 包名，走 custom 源（受安全开关控制）。\n   *  update=true 时对已安装目标放行覆盖重装（与目录插件「更新」同一语义）。\n   *  channel=入口渠道（NPM 包卡片）：上报服务端落日志，失败弹窗/通知据此精准溯源。\n   *  队列展示/防重一律用归一化身份：与服务端 /active 合并、弹窗目标匹配同口径，\n   *  npm 包名透传不受影响。 */\n  const installCustom = async (raw: string, opts?: { update?: boolean; channel?: InstallChannel }) => {\n    const target = raw.trim()\n    if (!target) return\n    const repo = repoFromInstallTarget(target)\n    await submitInstall({\n      target,\n      repo,\n      command: `pnpm add ${target}`,\n      source: 'custom',\n      update: opts?.update,\n      channel: opts?.channel,\n    })\n  }\n\n  /** 全局 npm 安装（官方 README 的 `npm install -g <pkgs>`）：不进任何 profile、无需宿主重启。\n   *  队列展示/防重用包列表空格拼接的身份（与服务端 target 同口径）；入口渠道固定为 npm（NPM 包卡片）。 */\n  const installGlobalNpm = async (pkgs: string[], opts?: { update?: boolean; channel?: InstallChannel }) => {\n    const list = (pkgs ?? []).map((p) => p.trim()).filter((p) => p !== '')\n    if (list.length === 0) return\n    const identity = list.join(' ')\n    await submitInstall({\n      target: identity,\n      repo: identity,\n      command: `npm install -g ${identity}`,\n      source: 'custom',\n      globalNpm: list,\n      update: opts?.update,\n      channel: opts?.channel ?? 'npm',\n    })\n  }\n\n  /** 卸载入队核心：按 npm 包名直卸（目录插件与自定义安装共用，弹窗进度匹配同源）。 */\n  const enqueueUninstall = async (name: string, repo: string | null, desc?: string) => {\n    if (!name) return\n    if (queueRef.current.some((q) => q.kind === 'uninstall' && q.target === name)) return\n    // 请求在途防重：与安装一致，响应回来前再次点击直接忽略\n    if (submittingRef.current.has(name)) return\n    submittingRef.current.add(name)\n    setSubmitting(true)\n    const controller = new AbortController()\n    const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS)\n    try {\n      const res = await fetch('/dsh-plugin-hub/uninstall', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ name, repo: repo ?? undefined }),\n        signal: controller.signal,\n      })\n      const data = await res.json() as { ok?: boolean; task?: number; error?: string }\n      if (!data.ok || typeof data.task !== 'number') {\n        onError(data.error || `HTTP ${res.status}`, repo, 'uninstall')\n        return\n      }\n      const taskId = data.task\n      modalTaskRef.current = taskId\n      applyQueue((prev) => [...prev, { id: taskId, kind: 'uninstall', target: name, desc, repo, status: 'pending', progress: 0, lines: [], needsRestart: true }])\n      // 摘要条常驻顶部（含实时进度），明细面板保持折叠，想看时再点开\n      pollQueue()\n    } catch (err) {\n      // 网络异常：附上底层原因，避免只剩一句笼统的「卸载失败」\n      const aborted = (err as { name?: string } | null)?.name === 'AbortError'\n      // [request-timeout]：给分类器一个与界面语言无关的超时标记\n      const reason = aborted\n        ? `${t('requestTimeout')}\\n[request-timeout]`\n        : err instanceof Error && err.message ? err.message : String(err ?? '')\n      onError(reason ? `${t('uninstallFail')} — ${reason}` : t('uninstallFail'), repo, 'uninstall')\n    } finally {\n      window.clearTimeout(timeout)\n      submittingRef.current.delete(name)\n      setSubmitting(false)\n    }\n  }\n\n  /** 弹窗动作：直接卸载（目录插件入口）。与安装同一队列机制，弹窗内实时显示进度。 */\n  const uninstallNow = async (p: HubPlugin) => {\n    const name = installedName(p)\n    if (!name) return\n    await enqueueUninstall(name, p.source?.repo ?? null, p.description)\n  }\n\n  /** 已安装视图动作：按已安装项卸载（覆盖目录外自定义安装，无目录数据也能卸）。 */\n  const uninstallItem = async (item: InstalledItem) => {\n    await enqueueUninstall(item.name, item.repo, item.plugin?.description)\n  }\n\n  /** 取消任务：排队中立即出队，执行中终止子进程；先标记「正在取消」短暂过渡后再移除。 */\n  const cancelTask = async (id: number) => {\n    if (modalTaskRef.current === id) modalTaskRef.current = null\n    // 乐观标记「正在取消」，给用户一个可见反馈，而不是瞬间消失\n    applyQueue((prev) => prev.map((q) => (q.id === id ? { ...q, status: 'cancelling' as const } : q)))\n    try {\n      await fetch('/dsh-plugin-hub/cancel', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ id }),\n      })\n    } catch { /* 服务端不可达：仍按取消处理，稍后移除 */ }\n    // 短暂展示「正在取消」后移除；队列清空则停止轮询\n    window.setTimeout(() => {\n      applyQueue((prev) => prev.filter((x) => x.id !== id))\n      maybeStopPoll()\n    }, 700)\n  }\n\n  /** 打开新弹窗前清空任务匹配：避免旧任务 id 误匹配到新弹窗。 */\n  const clearModalTask = () => { modalTaskRef.current = null }\n\n  // 弹窗对应任务：优先当前弹窗发起任务，其次按目标匹配（重新打开弹窗 / 目标已在队列时也能展示实时进度）\n  // 目录插件按 source.repo 匹配；命令行安装（custom）按归一化后的仓库身份/包名匹配；\n  // 全局 npm 安装按包列表身份（空格拼接）匹配；\n  // 排除 cancelling：取消中的任务不再关联到弹窗，弹窗回到「确认」态可重新操作\n  const installModalTarget = installPlugin?.source?.repo\n    ?? (installCustomTarget ? repoFromInstallTarget(installCustomTarget) : null)\n    ?? installGlobalTarget ?? null\n  const installModalTask = (installPlugin || installCustomTarget || installGlobalTarget)\n    ? (queue.find((q) => q.id === modalTaskRef.current && q.kind === 'install' && q.status !== 'cancelling')\n      ?? queue.find((q) => q.kind === 'install' && q.target === installModalTarget && q.status !== 'cancelling')\n      ?? null)\n    : null\n  const uninstallModalTask = (uninstallPlugin || uninstallName)\n    ? (queue.find((q) => q.id === modalTaskRef.current && q.status !== 'cancelling')\n      ?? queue.find((q) => q.kind === 'uninstall' && q.target === (uninstallName ?? installedName(uninstallPlugin!) ?? '') && q.status !== 'cancelling')\n      ?? null)\n    : null\n\n  return {\n    queue,\n    pendingRestarts,\n    installModalTask,\n    uninstallModalTask,\n    submitting,\n    installNow,\n    installCustom,\n    installGlobalNpm,\n    uninstallNow,\n    uninstallItem,\n    cancelTask,\n    clearModalTask,\n  }\n}\n"
    },
    {
      "path": "src/server/http/install.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 安装/卸载路由：校验目标后 spawn 官方 dsh CLI（见 services/install/install.ts），\n * 并回传捕获的结果。自定义安装只接受 npm 包名。\n */\nimport { githubRepoOf, globalNpmPackagesOf, hasQueuedTarget, installTargetOf, startPluginMutation, validPackageName, type LoaderHandle } from '../services/install/install.ts'\nimport { recordResolvedNpmPackage } from '../services/profile/installed-versions.ts'\nimport { isDshNpmPackageForRepo } from '../services/install/npm-resolve.ts'\nimport { probeUrl, systemProxy } from '../services/probe.ts'\nimport { loadSettings, type HubSettings } from '../services/settings.ts'\nimport { registryCandidates, registryHost, userNpmRegistry } from '../services/install/registry-fallback.ts'\nimport { profileDirectory } from '../services/profile/profile.ts'\nimport { readInstalled } from './catalog.ts'\nimport { COMMAND_TIMEOUT_MS, readJsonBody, requireTrustedPost, sendJson, type WebRoute, type WebServerService } from './shared.ts'\n\n/** 安装/卸载 CLI 的子进程环境：透传宿主环境并注入 HTTP(S) 代理，\n *  代理来源与诊断一致（设置代理 → 系统代理 → 宿主 env）；registry 由任务队列按候选源逐次注入。 */\nfunction mutationEnv(settings: HubSettings): NodeJS.ProcessEnv {\n  const env: NodeJS.ProcessEnv = { ...process.env, CI: 'true' }\n  const proxy = settings.proxy !== '' ? settings.proxy : (systemProxy() ?? '')\n  if (proxy !== '') {\n    env.HTTP_PROXY = proxy\n    env.HTTPS_PROXY = proxy\n    env.http_proxy = proxy\n    env.https_proxy = proxy\n  }\n  return env\n}\n\nexport function registerInstallRoutes(webServer: WebServerService, profile: string, loader: LoaderHandle | undefined): WebRoute[] {\n  return [\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/install',\n      handler: async (request, response) => {\n        if (!requireTrustedPost(request, response)) return\n        // 任务自动入队：即使已有插件操作在跑也接受请求（FIFO 串行执行），不做 409 拒绝\n        try {\n          const body = await readJsonBody(request)\n          // mode: 'update' = 已安装目标的覆盖更新（放行 add，pnpm 对已存在依赖原位覆盖重装）。\n          let mode = body !== null && typeof body === 'object' && (body as { mode?: unknown }).mode === 'update'\n            ? 'update'\n            : 'install'\n          // installTargetOf 把完整 DSH 命令剥成裸目标；自定义目标只接受 npm 包名，语法判定交给 validPackageName。\n          const rawRepo = typeof body === 'object' && body !== null && typeof (body as { repo?: unknown }).repo === 'string'\n            ? installTargetOf((body as { repo: string }).repo)\n            : ''\n          // 展示用仓库名（owner/repo）：npm 安装时 body.repo 是包名，display 供待重启行 / 任务恢复展示仓库名。\n          const displayRepo = typeof body === 'object' && body !== null && typeof (body as { display?: unknown }).display === 'string'\n            ? (body as { display: string }).display.trim()\n            : rawRepo\n          // 请求来源：目录插件安装（catalog）走目录白名单；命令行安装（custom）受安全开关控制\n          const source = typeof body === 'object' && body !== null && typeof (body as { source?: unknown }).source === 'string'\n            ? (body as { source: string }).source\n            : ''\n          // 自定义安装入口渠道（仅 NPM 包）：日志/报错据此溯源发起入口。\n          const installChannel = (() => {\n            const raw = body !== null && typeof body === 'object' ? (body as { installChannel?: unknown }).installChannel : undefined\n            return raw === 'npm' ? 'npm' : undefined\n          })()\n          const settings = loadSettings(profile)\n          // 界面语言（客户端随请求携带）：错误消息按用户当前语言提示（中文界面给中文，英文界面给英文）\n          const lang = typeof body === 'object' && body !== null && (body as { lang?: unknown }).lang === 'en'\n            ? 'en'\n            : 'zh'\n          // 代理口径与诊断/安装通道一致：设置里的代理 → 系统代理 → 环境变量 → 直连。\n          const effectiveProxy = settings.proxy !== ''\n            ? settings.proxy\n            : (systemProxy() ?? process.env.HTTPS_PROXY ?? process.env.https_proxy ?? '')\n          // 安装用的 npm 源：设置里显式选择优先；未配置时读本机 npm 配置（与诊断同口径）。\n          // 只有公共源允许失败后换源；自定义/内网源保持单一候选，避免私有包名泄露给公共源。\n          const registries = registryCandidates(\n            settings.npmRegistry,\n            settings.npmRegistry === '' ? userNpmRegistry(profileDirectory(profile)) : '',\n            settings.registryFallback,\n          )\n          // 全局 npm 安装（`npm install -g <pkgs>`）：不进任何 profile、无需宿主重启。\n          // 包列表优先取 body.globalNpm，兜底从 rawRepo 解析，保证直接调 API 传完整命令也能识别。\n          const bodyGlobalNpm = Array.isArray((body as { globalNpm?: unknown }).globalNpm)\n            ? (body as { globalNpm: unknown[] }).globalNpm.filter((x): x is string => typeof x === 'string' && x !== '')\n            : []\n          const globalNpm: string[] = bodyGlobalNpm.length > 0 ? bodyGlobalNpm : (globalNpmPackagesOf(rawRepo) ?? [])\n          if (globalNpm.length > 0) {\n            // 包名逐个按 npm 包名语法校验 + 拒绝以 - 开头的 token（npm 会把 --xxx 当参数而非包名），数量封顶防滥用\n            if (globalNpm.length > 20 || globalNpm.some((p) => !validPackageName(p) || p.startsWith('-'))) {\n              sendJson(response, 400, { error: 'unsupported install target' })\n              return\n            }\n            // 通道门禁与安装通道同构：全局安装本质是 npm 操作，吃「启用 NPM 安装」开关\n            if (source !== 'catalog' && !settings.enableNpmInstall) {\n              sendJson(response, 403, { error: 'npm installs are disabled by the security settings' })\n              return\n            }\n            // 队列级去重：同一包列表已在排队/执行中时拒绝\n            const identity = globalNpm.join(' ')\n            if (hasQueuedTarget(identity)) {\n              sendJson(response, 409, { error: `already queued: ${identity}` })\n              return\n            }\n            const task = startPluginMutation({\n              action: 'add',\n              profile,\n              target: identity,\n              displayTarget: identity,\n              globalNpm,\n              timeoutMs: COMMAND_TIMEOUT_MS,\n              env: mutationEnv(settings),\n              // 候选源（首选在前）：任务内遇到传输层失败时按顺序换源重试\n              registries,\n              // 全局 npm 安装由 NPM 包卡片/官方命令发起：日志体现入口渠道\n              installChannel: installChannel ?? 'npm',\n            })\n            sendJson(response, 200, { ok: true, task: task.id })\n            return\n          }\n          // 自定义安装目标只接受 npm 包名（@scope/name 或 name）。\n          if (!validPackageName(rawRepo)) {\n            sendJson(response, 400, { error: 'unsupported install target: expected an npm package name' })\n            return\n          }\n          const target = rawRepo\n          // 钉住精确版本（Hub 自我更新）：最新版可能仍在 pnpm 供应链门禁内，\n          // 客户端提示的是「已过门禁」的版本，服务端必须按该版本安装而不是 @latest。\n          const pinVersion = typeof (body as { version?: unknown }).version === 'string'\n            ? (body as { version: string }).version.trim()\n            : ''\n          if (pinVersion !== '' && !/^\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z.]+)?$/.test(pinVersion)) {\n            sendJson(response, 400, { error: 'invalid version' })\n            return\n          }\n          // 已尝试的安装方式（供失败提 Issue 预填）：保持为空\n          const attempts: string[] = []\n          // 目录插件安装：目录数据可能滞后于打包拆分，确认目录下发的 npm 目标确为该仓库的 DSH 包，\n          // 命中则记录 repo → 包名映射，客户端据此把依赖 key 匹配回仓库、列表立即显示「已安装」。\n          const catalogRepo = source === 'catalog' ? githubRepoOf(displayRepo) : null\n          if (catalogRepo !== null) {\n            const catalogTargetIsDsh = await isDshNpmPackageForRepo(rawRepo, catalogRepo, settings.npmRegistry, effectiveProxy)\n            if (catalogTargetIsDsh) recordResolvedNpmPackage(profile, catalogRepo, rawRepo)\n          }\n          // 命令行安装（目录外）受「启用 NPM 安装」开关控制；目录插件安装走目录白名单，不受开关影响。\n          if (source !== 'catalog' && !settings.enableNpmInstall) {\n            sendJson(response, 403, { error: 'npm installs are disabled by the security settings' })\n            return\n          }\n          // 命中已安装目标时按「更新」执行（pnpm add 对已存在依赖即原位覆盖重装）：\n          // 客户端已装列表可能与服务端不同步，覆盖重装比报错更友好且终态一致。\n          const installed = readInstalled(profile)\n          const already = installed[target] !== undefined ? target : null\n          if (already !== null) mode = 'update'\n          // 队列级去重：同一目标已在排队/执行中时拒绝，避免客户端防重竞态导致重复入队\n          if (hasQueuedTarget(target)) {\n            sendJson(response, 409, { error: `already queued: ${target}` })\n            return\n          }\n          // 安装前网络探测：探 registry 根而非具体包（404 是「包不存在」而非网络不通）；仅新安装执行，更新跳过。\n          // 首选源不通时按候选顺序继续探下一个，能通的那个提到首位供实际安装使用。\n          // 全部不通则 400 拦下并打 [network] 标记，客户端据此提示网络问题，而非插件问题。\n          let ordered = registries\n          if (already === null) {\n            const tried: string[] = []\n            let chosen: string | null = null\n            for (const candidate of registries) {\n              tried.push(candidate)\n              const net = await probeUrl(`${candidate}/`, effectiveProxy, 6000)\n              if (net.ok) {\n                chosen = candidate\n                break\n              }\n            }\n            if (chosen === null) {\n              // 错误消息按界面语言输出，让用户看清是网络问题而非插件问题\n              const hosts = tried.map(registryHost).join(' → ')\n              const error = lang === 'zh'\n                ? `[network] 安装已中止：安装前无法连接到 npm 源（${hosts}）—— 您的网络似乎不通或被拦截（断网 / DNS 解析失败 / 防火墙 / 代理配置问题）。这不是插件本身的问题，请检查网络连接或代理设置，运行「系统诊断」检测各通道连通性后重试。`\n                : `[network] install aborted: cannot reach the npm registry (${hosts}) before install — your network connection appears to be down or blocked (DNS / proxy / firewall). This is not a problem with the plugin itself. Check your connection or proxy settings, run the connectivity diagnostic, then retry.`\n              sendJson(response, 400, { error, attempts })\n              return\n            }\n            ordered = [chosen, ...registries.filter((r) => r !== chosen)]\n          }\n          // 入队前复检：网络探测的 await 期间并发请求可能已通过上方检查，而此处到 startPluginMutation\n          // 之间无 await，JS 单线程保证同一目标至多一个任务，杜绝双击/并发双任务。\n          if (hasQueuedTarget(target)) {\n            sendJson(response, 409, { error: `already queued: ${target}` })\n            return\n          }\n          // 后台启动 CLI；客户端轮询 /status 获取进度\n          const task = startPluginMutation({\n            // mode=update（已安装目标的覆盖更新）以 update 动作入队：\n            // 日志按 update 类别落盘（update.start/done/fail），实际 CLI 执行仍是 add <target>@latest\n            action: mode === 'update' ? 'update' : 'add',\n            profile,\n            target,\n            // npm 安装时 target 是包名：displayTarget 固定展示仓库名，待重启行/前端恢复不因安装目标形态而变\n            displayTarget: githubRepoOf(displayRepo) ?? undefined,\n            // 覆盖更新：npm 命令显式 @latest（pnpm add 无版本对已存在依赖是幂等的，不加版本不会真更新）\n            updateNpm: mode === 'update',\n            // 运行中 loader：安装成功后把新插件热挂进 loader，非桌面端 + 纯服务端插件无需重启即生效\n            loader,\n            timeoutMs: COMMAND_TIMEOUT_MS,\n            env: mutationEnv(settings),\n            // 候选源（首选在前）：任务内遇到传输层失败时按顺序换源重试\n            registries: ordered,\n            installSpec: pinVersion !== '' ? `${target}@${pinVersion}` : undefined,\n            // 自定义安装入口渠道：日志/报错据此溯源\n            installChannel,\n          })\n          sendJson(response, 200, { ok: true, task: task.id })\n        } catch (error) {\n          sendJson(response, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/uninstall',\n      handler: async (request, response) => {\n        if (!requireTrustedPost(request, response)) return\n        // 与安装一致：卸载也进入同一队列，FIFO 串行执行\n        try {\n          const body = await readJsonBody(request)\n          const name = typeof body === 'object' && body !== null && typeof (body as { name?: unknown }).name === 'string'\n            ? (body as { name: string }).name\n            : ''\n          // 展示用的 owner/repo：卸载命令只需要 npm 包名，但待重启行要与安装行一致地显示仓库名\n          const repo = typeof body === 'object' && body !== null && typeof (body as { repo?: unknown }).repo === 'string'\n            ? (body as { repo: string }).repo\n            : ''\n          if (!validPackageName(name) || name === 'dsh-plugin') {\n            sendJson(response, 400, { error: 'plugin cannot be uninstalled here' })\n            return\n          }\n          if (readInstalled(profile)[name] === undefined) {\n            sendJson(response, 400, { error: 'plugin is not installed' })\n            return\n          }\n          // 队列级去重：同一包已在排队/执行中卸载时拒绝\n          if (hasQueuedTarget(name)) {\n            sendJson(response, 409, { error: `already queued: ${name}` })\n            return\n          }\n          const task = startPluginMutation({\n            action: 'remove',\n            profile,\n            target: name,\n            // 卸载的 mutation 目标是 npm 包名；待重启行要显示 owner/repo（与安装行一致），非法/缺失时回退包名\n            displayTarget: githubRepoOf(repo) ?? undefined,\n            // 运行中 loader：卸载成功后主动移除条目，立即生效、无需重启\n            loader,\n            timeoutMs: COMMAND_TIMEOUT_MS,\n            env: mutationEnv(loadSettings(profile)),\n          })\n          sendJson(response, 200, { ok: true, task: task.id })\n        } catch (error) {\n          sendJson(response, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n  ]\n}\n"
    },
    {
      "path": "src/server/services/install/task-queue.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 后台安装/卸载任务队列：内存任务注册表 + FIFO 串行 worker + 子进程生命周期管理。\n * 每个任务一次 `dsh plugin --profile <profile> <action> <target>` 子进程，\n * 输出流式收集到任务上；卸载成功时尝试从运行中 loader 即时停用（见 loader.ts）。\n */\nimport { spawn, spawnSync } from 'node:child_process'\nimport { requiredDistributionFiles, resolveBundlePatchFiles, type PackageManifest } from './package-entry.ts'\nimport { existsSync, readFileSync, statSync } from 'node:fs'\nimport { dirname, join, resolve } from 'node:path'\nimport type { InstallResult, InstallTask, Invocation, QueueItem } from './install-types.ts'\nimport { CAPTURE_LIMIT_BYTES, MAX_TASKS, MAX_TASK_LINES } from './install-types.ts'\nimport { npmTooLowMarker } from './npm-check.ts'\nimport { registryMissingMarker } from './registry-check.ts'\nimport { backfillOperationLog, createOperationLogTap, hasSubstantiveOutput, operationLogPathOf } from './operation-log.ts'\nimport { cleanLine, estimateProgress } from '../profile/progress.ts'\nimport type { LoaderHandle } from '../loader.ts'\nimport { hasClientUi, isDshPlugin, mountLoadedEntry, removeLoadedEntry } from '../loader.ts'\nimport { addPendingRestart, clearPendingRestart } from '../profile/pending-restart.ts'\nimport { addAllowBuildsKey, bundleIncludes, githubRepoOf, parseAllowBuildsKey, profileDirectory, validPackageName } from '../profile/profile.ts'\nimport { appendLog } from '../log.ts'\nimport { commandOnPath, gitMissingDetail } from './preflight.ts'\nimport { isTransportFailure, registryHost } from './registry-fallback.ts'\nimport { dshTooOldMarker } from './dsh-compat.ts'\nimport { OutputDecoder } from './decode-output.ts'\nimport { profileYamlMarker } from './profile-yaml.ts'\nimport { runtimeExecPath } from '../runtime-exec.ts'\n\n/** 内存任务注册表，按任务 id 索引。 */\nconst tasks = new Map<number, InstallTask>()\nlet nextTaskId = 1\n/** 等待轮到的排队任务（FIFO）。队列 worker 同一时刻最多跑一个变更。 */\nconst queue: QueueItem[] = []\n/** 当前运行任务的子进程（用于取消）。 */\nconst runningChildren = new Map<number, ReturnType<typeof spawn>>()\n\n/** 任务快照（避免消费方改动实时对象）。 */\nexport function getTask(id: number): InstallTask | undefined {\n  const task = tasks.get(id)\n  if (!task) return undefined\n  return { ...task, lines: task.lines.slice(0, MAX_TASK_LINES) }\n}\n\nexport interface ActiveTaskInfo {\n  id: number\n  target: string\n  action: 'add' | 'remove' | 'update'\n  status: 'pending' | 'running'\n  progress: number\n  lines: string[]\n  /** 尝试过的安装方式（实际执行过的命令）：失败时前端 issue 预填需要 */\n  attempts: string[]\n  /** 自定义安装入口渠道（NPM 包卡片）：前端刷新恢复后仍能精准溯源 */\n  installChannel?: 'npm'\n}\n\n/** 全部未终态任务，按队列顺序（running 在前、pending 在后）。供客户端刷新页面后恢复队列。 */\nexport function activeTask(): ActiveTaskInfo[] {\n  const found: ActiveTaskInfo[] = []\n  // 展示目标用 displayTarget（owner/repo）：安装 target 是 npm 包名，\n  // 队列恢复/待重启展示对用户保持仓库名无感知\n  const show = (task: InstallTask): string => task.displayTarget ?? task.target\n  for (const item of queue) {\n    const task = item.task\n    if (task.status === 'pending') {\n      found.push({\n        id: task.id,\n        target: show(task),\n        action: task.action,\n        status: 'pending',\n        progress: task.progress,\n        lines: task.lines.slice(0, MAX_TASK_LINES),\n        attempts: task.attempts,\n        installChannel: task.installChannel,\n      })\n    }\n  }\n  tasks.forEach((task) => {\n    if (task.status === 'running') {\n      found.unshift({\n        id: task.id,\n        target: show(task),\n        action: task.action,\n        status: 'running',\n        progress: task.progress,\n        lines: task.lines.slice(0, MAX_TASK_LINES),\n        attempts: task.attempts,\n        installChannel: task.installChannel,\n      })\n    }\n  })\n  return found\n}\n\n/**\n * 变更子进程仍存活时为 true。并发占位以存活子进程集合为准，而非 task.status：\n * 取消运行中任务会立即翻转其状态，但子进程可能仍在退出中（close 事件稍后才到）——\n * 占位必须维持到那时，否则旧 pnpm 还在同一 profile 目录跑，新任务就开始了。\n */\nexport function hasRunningTask(): boolean {\n  return runningChildren.size > 0\n}\n\n/** 目标在队列里是否已有未终态任务（安装/卸载去重）。 */\nexport function hasQueuedTarget(target: string): boolean {\n  return queue.some((it) => it.task.target === target && (it.task.status === 'pending' || it.task.status === 'running'))\n}\n\n/**\n * 取消排队中或运行中的任务。\n * - pending：立即移出队列（从未 spawn）。\n * - running：杀掉子进程；队列 worker 随后取下一个。\n * 任务不存在或已结束时返回 false。\n */\nexport function cancelTask(id: number): boolean {\n  const task = tasks.get(id)\n  if (!task) return false\n  if (task.status === 'pending') {\n    const index = queue.findIndex((it) => it.task === task)\n    if (index >= 0) queue.splice(index, 1)\n    task.status = 'cancelled'\n    pushLine(task, '[cancelled]')\n    return true\n  }\n  if (task.status === 'running') {\n    task.status = 'cancelled'\n    pushLine(task, '[cancelled]')\n    const child = runningChildren.get(id)\n    if (child) stopChild(child)\n    return true\n  }\n  return false\n}\n\nfunction pushLine(task: InstallTask, line: string): void {\n  const text = cleanLine(line)\n  // pnpm 的 `Progress:` 行用 \\r 原地刷新同一行：内容一变化就追加，\n  // 日志像终端一样实时滚动（downloaded 0→1→2…）；内容与最新一条完全相同则跳过，\n  // 避免同一进度反复刷新时无意义的重复堆积\n  if (text !== task.lines[0]) {\n    task.lines.unshift(text)\n    if (task.lines.length > MAX_TASK_LINES) task.lines.length = MAX_TASK_LINES\n  }\n  const estimate = estimateProgress(text)\n  if (estimate > 0) {\n    task.progress = Math.max(task.progress, estimate)\n  } else if (task.status === 'running' && task.progress < 85) {\n    // 兜底：行无解析格式也随输出量推进，保证进度条始终在动（不会卡在 0）\n    task.progress = Math.max(task.progress, 6 + Math.min(79, task.lines.length * 2))\n  }\n}\n\n/** spawn 的 cwd：profile 目录（asar 路径不能作 cwd）；目录不存在时回退进程工作目录，\n *  否则 Node 报的是 `spawn <file> ENOENT`，与「可执行文件不存在」无法区分。 */\nfunction spawnCwdFor(profile: string): string {\n  const dir = profileDirectory(profile)\n  return existsSync(dir) ? dir : process.cwd()\n}\n\nfunction cliInvocation(profile: string): Invocation {\n  const entry = process.argv[1]\n  if (entry !== undefined) {\n    // 打包桌面端（Electron）：宿主入口在 app.asar 内，机器上根本没有 `dsh` 可执行文件\n    //（Windows 那条 dsh.cmd shim 只存在于宿主进程自己的 PATH 里），直接回退 PATH 必然\n    // 报 [dsh-missing]。这里改用应用自己的 CLI 引导脚本调起同一份打包\n    // CLI：Electron 可执行文件 + --expose-internals + desktop-cli.js，与内置终端、\n    // 官方插件页安装完全同一条路径 —— desktop profile 由应用独占管理的授权也在其中。\n    const bootstrap = desktopCliBootstrap(entry)\n    if (bootstrap !== null) {\n      return {\n        // Android 上 execPath 是 linker64，直接用会把 --expose-internals 当可执行文件\n        file: runtimeExecPath(),\n        prefixArgs: ['--expose-internals', bootstrap],\n        // cwd 用 profile 目录（asar 路径不能作 cwd），不存在时由 spawnCwdFor 回退\n        cwd: spawnCwdFor(profile),\n        useShell: false,\n        // Electron 可执行文件只有带这个变量才按 Node 运行引导脚本\n        env: { ELECTRON_RUN_AS_NODE: '1' },\n      }\n    }\n    if (/[\\\\/](?:bin\\.(?:js|ts)|dsh)$/.test(entry)) {\n      const absoluteEntry = resolve(entry)\n      return {\n        file: runtimeExecPath(),\n        prefixArgs: [...process.execArgv, absoluteEntry],\n        cwd: dirname(absoluteEntry),\n        useShell: false,\n      }\n    }\n  }\n  return { file: 'dsh', prefixArgs: [], cwd: process.cwd(), useShell: process.platform === 'win32' }\n}\n\n/**\n * 打包桌面端宿主的 CLI 引导脚本路径（`<asar 根>/lib/desktop-cli.js`，即应用内\n * pnpm 服务的 dshBootstrapPath）。宿主入口落在 app.asar 内时按 asar 根反推候选路径，\n * 命中存在的那个才采用；布局不认识（官方改版）时返回 null，调用方回退原逻辑。\n * 导出供单测覆盖路径推导。\n */\nexport function desktopCliBootstrap(entry: string): string | null {\n  const marker = /[\\\\/]app\\.asar(?=[\\\\/]|$)/i.exec(entry)\n  if (marker === null) return null\n  const root = entry.slice(0, marker.index + marker[0].length)\n  const candidates = [\n    join(root, 'lib', 'desktop-cli.js'),\n    join(root, 'dsh', 'lib', 'desktop-cli.js'),\n    // DeepSeek Harness 0.2.x 的布局：宿主入口本身就是 @deepseek-ai/dsh-desktop-host/lib/index.js，\n    // 保留档 CLI 是它同目录的 cli.js（内部以 manageDesktopProfile 放行 desktop 档的插件管理）。\n    // 漏掉这个布局就会回退 PATH 上的 dsh，而 `dsh plugin --profile desktop …` 必被\n    // 「profile desktop is managed exclusively by the Electron application」拒绝 —— 桌面端全部安装失败。\n    join(dirname(entry), 'cli.js'),\n  ]\n  for (const candidate of candidates) {\n    if (existsSync(candidate)) return candidate\n  }\n  return null\n}\n\n/**\n * 传给 CLI 的安装目标：钉住版本优先（Hub 自我更新提示的是已过供应链门禁的版本），\n * 其次 npm 的 add/update 都显式 `@latest`；git 源、全局安装、已带版本/tag 的 spec 保持原样。\n */\nexport function npmInstallTargetOf(target: string, opts: { update: boolean; global: boolean; pinned?: string; add?: boolean }): string {\n  if (opts.global || githubRepoOf(target) !== null) return target\n  if (opts.pinned !== undefined && opts.pinned !== '') return opts.pinned\n  // 裸包名才补 @latest：pnpm 对已存在的精确 spec 是幂等的，不显式要求就会留用旧版本\n  if (!(opts.update || opts.add) || !validPackageName(target)) return target\n  return `${target}@latest`\n}\n\nfunction stopChild(child: ReturnType<typeof spawn>): void {\n  if (process.platform === 'win32' && child.pid !== undefined) {\n    const killer = spawn('taskkill', ['/pid', String(child.pid), '/t', '/f'], { stdio: 'ignore' })\n    killer.once('error', () => child.kill('SIGKILL'))\n    return\n  }\n  if (child.pid !== undefined) {\n    // POSIX：dsh 内部会 fork pnpm，只杀 dsh 会让 pnpm 变成孤儿继续攥着管道，\n    // close 事件永不到来、队列卡死。detached 让子进程成为进程组组长，\n    // 对整组 SIGKILL 才能把 dsh + pnpm（及后代）一起清掉，close 随即触发。\n    try {\n      process.kill(-child.pid, 'SIGKILL')\n      return\n    } catch { /* 进程已退出：忽略 */ }\n  }\n  child.kill('SIGKILL')\n}\n\n/** 系统日志类别：安装/卸载/更新三分，针对性地判断「哪一步不兼容」。 */\nfunction mutationCategory(action: 'add' | 'remove' | 'update'): 'install' | 'uninstall' | 'update' {\n  return action === 'remove' ? 'uninstall' : action === 'update' ? 'update' : 'install'\n}\n\n/** 系统日志动作词：开始安装/开始卸载/开始更新。 */\nfunction mutationVerb(action: 'add' | 'remove' | 'update'): string {\n  return action === 'remove' ? '开始卸载' : action === 'update' ? '开始更新' : '开始安装'\n}\n\n/** 系统日志入口渠道后缀：自定义安装（带渠道）在日志里体现「从哪张卡片发起」，\n *  目录插件安装（无渠道）返回空串。日志中文语境，渠道名用中文口语。 */\nfunction channelLabel(channel: 'npm' | undefined): string {\n  if (channel === 'npm') return '（NPM 包入口）'\n  return ''\n}\n\n/**\n * 插件变更入队并返回其任务。任务严格串行：队列 worker 只在上一个结束后才启动下一个。\n * 完成前可通过 `getTask(id)` / `activeTask()` 查看进度。\n */\nexport function startPluginMutation(options: {\n  action: 'add' | 'remove' | 'update'\n  profile: string\n  target: string\n  timeoutMs?: number\n  env?: NodeJS.ProcessEnv\n  /** 全局 npm 安装（官方 `npm install -g <pkgs>`）：非空时执行全局安装，不进任何 profile、无需宿主重启 */\n  globalNpm?: string[]\n  /** 待重启行的展示目标（owner/repo）：卸载时用于把 npm 包名映射回仓库名 */\n  displayTarget?: string\n  /** 运行中 loader：安装成功后热挂新条目、卸载成功后停用旧条目，两类操作都尽量立即生效\n   *  （缺失时安装/卸载仍需重启） */\n  loader?: LoaderHandle\n  /** 入队前已尝试的安装方式：失败提 Issue 时如实展示；实际执行的命令由 spawn 时追加 */\n  attempts?: string[]\n  /** 更新已安装的 npm 包（mode=update）：命令显式带 @latest，让 pnpm 真正解析最新版本 */\n  updateNpm?: boolean\n  /** 自定义安装入口渠道（NPM 包卡片）：任务输出行与系统日志据此溯源「从哪个入口发起」；\n   *  目录插件安装不传 */\n  installChannel?: 'npm'\n  /** npm 源候选（首选在前）：传输层失败时按顺序换源重试，空/单个表示不降级 */\n  registries?: string[]\n  /** 精确安装 spec（如 `dsh-plugin@2.0.5`）：Hub 自我更新提示的是已过供应链门禁的版本，\n   *  必须钉住安装，不能再用 @latest 被带回门禁内的最新版 */\n  installSpec?: string\n}): InstallTask {\n  // 卸载入队时先快照「该包是否带客户端 UI」：卸载完成后包已从磁盘删除，读不到 package.json，\n  // 只能在此刻取；卸载成功且曾存活时据此决定是否要刷新页面摘除插件面板\n  const hadClientUi = options.action === 'remove' ? hasClientUi(options.profile, options.target) : undefined\n  const task: InstallTask = {\n    id: nextTaskId,\n    target: options.target,\n    displayTarget: options.displayTarget,\n    globalNpm: options.globalNpm,\n    action: options.action,\n    status: 'pending',\n    timedOut: false,\n    exitCode: null,\n    progress: 0,\n    lines: [],\n    attempts: options.attempts ?? [],\n    needsRestart: false,\n    hadClientUi,\n    installChannel: options.installChannel,\n  }\n  nextTaskId = nextTaskId >= Number.MAX_SAFE_INTEGER ? 1 : nextTaskId + 1\n  tasks.set(task.id, task)\n  if (tasks.size > MAX_TASKS) {\n    let removed = false\n    tasks.forEach((candidate, id) => {\n      if (!removed && candidate.status !== 'running' && candidate.status !== 'pending') {\n        tasks.delete(id)\n        removed = true\n      }\n    })\n  }\n  queue.push({ task, options: { ...options } })\n  // 任务输出首行标记入口渠道（ASCII 标记，乱码免疫）：进度面板/失败明细里能溯源「从哪张卡片发起」\n  if (options.installChannel !== undefined) {\n    pushLine(task, `[install-channel] ${options.installChannel}`)\n  }\n  // 系统日志：记录任务入队（安装/卸载/更新开始），自定义安装带入口渠道后缀\n  const category = mutationCategory(options.action)\n  appendLog(options.profile, {\n    at: Date.now(),\n    level: 'info',\n    category,\n    event: `${category}.start`,\n    message: `${mutationVerb(options.action)} ${options.displayTarget ?? options.target}${channelLabel(options.installChannel)}`,\n  })\n  pumpQueue()\n  return task\n}\n\n/** 队列 worker：同一时刻最多跑一个变更；占位空出时取下一个 pending 任务。 */\nfunction pumpQueue(): void {\n  if (hasRunningTask()) return\n  const item = queue.find((it) => it.task.status === 'pending')\n  if (!item) return\n  const { task, options } = item\n  task.status = 'running'\n  void runPluginMutation({ ...options, task })\n    .catch((error) => {\n      // runPluginMutation 的恢复路径（如 allowBuilds 写回 pnpm-workspace.yaml）\n      // 可能抛出；落到 failed 终态并留痕，否则该 Promise 链成为未处理 rejection\n      //（Node >= 15 默认直接终止进程），而队列自身却在 finally 里继续 pump。\n      if (task.status !== 'cancelled') {\n        task.status = 'failed'\n        task.exitCode = null\n        task.progress = 0\n        pushLine(task, `[internal] ${error instanceof Error ? error.message : String(error)}`)\n      }\n    })\n    .finally(() => {\n    runningChildren.delete(task.id)\n    // 系统日志：任务终态（成功/失败/取消），按动作归类安装/卸载/更新日志\n    const show = task.displayTarget ?? task.target\n    const category = mutationCategory(task.action)\n    const verb = (v: '成功' | '失败') => task.action === 'remove' ? `卸载${v}` : task.action === 'update' ? `更新${v}` : `安装${v}`\n    if (task.status === 'done') {\n      appendLog(options.profile, {\n        at: Date.now(),\n        level: 'success',\n        category,\n        event: `${category}.done`,\n        message: `${verb('成功')} ${show}${channelLabel(options.installChannel)}${task.needsRestart ? '（待重启生效）' : ''}`,\n      })\n    } else if (task.status === 'failed') {\n      appendLog(options.profile, {\n        at: Date.now(),\n        level: 'error',\n        category,\n        event: `${category}.fail`,\n        message: `${verb('失败')} ${show}${channelLabel(options.installChannel)}`,\n      })\n    } else if (task.status === 'cancelled') {\n      appendLog(options.profile, {\n        at: Date.now(),\n        level: 'warn',\n        category,\n        event: 'task.cancel',\n        message: `已取消 ${show}${channelLabel(options.installChannel)}`,\n      })\n    }\n    // 已终态的任务移出队列：既防 queue 数组无限增长（内存泄漏），也让下一轮 pump 干净\n    const idx = queue.findIndex((it) => it.task === task)\n    if (idx >= 0) queue.splice(idx, 1)\n    pumpQueue()\n  })\n}\n\n/**\n * 执行一次 `dsh plugin --profile <profile> <action> <target>` spawn，把输出流式写到\n * 跟踪的任务上，并以捕获结果 resolve。绝不 reject；失败通过结果/任务状态体现。\n */\nfunction spawnMutation(options: {\n  action: 'add' | 'remove' | 'update'\n  profile: string\n  target: string\n  timeoutMs?: number\n  env?: NodeJS.ProcessEnv\n  task?: InstallTask\n  /** 待重启行的展示目标（owner/repo）：与 mutation 目标解耦——卸载的 mutation 目标是 npm 包名，展示要回退到仓库名 */\n  displayTarget?: string\n  /** 运行中 loader：安装成功后热挂新条目、卸载成功后停用旧条目（缺失时仍需重启） */\n  loader?: LoaderHandle\n  /** 全局 npm 安装（官方 `npm install -g <pkgs>`）：非空时执行全局安装，不进任何 profile、无需宿主重启 */\n  globalNpm?: string[]\n  /** 更新已安装的 npm 包（mode=update）：命令显式带 @latest，让 pnpm 真正解析最新版本 */\n  updateNpm?: boolean\n  /** npm 源候选（首选在前）：传输层失败时按顺序换源重试 */\n  registries?: string[]\n  /** 精确安装 spec（如 `dsh-plugin@2.0.5`）：见 startPluginMutation 同名说明 */\n  installSpec?: string\n}): Promise<InstallResult> {\n  const { action, profile, target, timeoutMs = 5 * 60 * 1000, env, task, displayTarget, loader, globalNpm, updateNpm, registries, installSpec } = options\n  // 全局 npm 安装：直接 spawn 本机 npm（`npm install -g <pkgs>`），不是 dsh plugin 命令\n  const isGlobalNpm = (globalNpm ?? []).length > 0\n  const invocation = isGlobalNpm\n    ? { file: 'npm', prefixArgs: [], cwd: process.cwd(), useShell: process.platform === 'win32' }\n    : cliInvocation(profile)\n  // 打包桌面端却回退到 PATH 上的 dsh：说明 desktop CLI 引导路径没命中，desktop profile 必被宿主拒绝。\n  // 留一行 ASCII 标记，后续同类上报可直接区分「用户自起 CLI」与「我们没走对引导路径」。\n  if (task && task.status !== 'cancelled' && invocation.file === 'dsh'\n    && (process.versions as Record<string, string | undefined>).electron !== undefined) {\n    pushLine(task, '[desktop-cli-fallback] running inside Electron but no desktop CLI bootstrap was found — falling back to dsh on PATH (a desktop-managed profile will be rejected)')\n  }\n  // 安装/更新 npm 包都显式 @latest：pnpm add <pkg>（无版本）对已存在的精确 spec 是幂等的，\n  // 会原样留用旧版本（更新不生效，普通安装也可能装回不支持当前宿主的旧包）。\n  // update 动作同样执行 `add <target>@latest`，CLI 动词透传 add，不与官方 update 动词分叉。\n  const isUpdate = action === 'update' || updateNpm === true\n  const cliAction = action === 'update' ? 'add' : action\n  // 钉住版本优先于 @latest：提示的是「已过门禁」的版本，装 latest 会被 pnpm 拒绝\n  const npmUpdateTarget = npmInstallTargetOf(target, { update: isUpdate, global: isGlobalNpm, pinned: installSpec, add: cliAction === 'add' })\n  const args = isGlobalNpm\n    ? ['install', '-g', ...(globalNpm ?? [])]\n    : [...invocation.prefixArgs, 'plugin', '--profile', profile, cliAction, npmUpdateTarget]\n  // 记录实际执行的命令（显示包名），失败提 Issue 时作为「已尝试的安装方式」随附\n  const executed = isGlobalNpm\n    ? `npm install -g ${(globalNpm ?? []).join(' ')}`\n    : `dsh plugin --profile ${profile} ${cliAction} ${npmUpdateTarget}`\n  if (task && !task.attempts.includes(executed)) {\n    task.attempts.push(executed)\n  }\n  // 单次 spawn 并捕获结果：流式输出打日志 + 超时/取消兜底，close 后 resolve。\n  // 不做任何终态后处理（exitCode/status/needsRestart 由下方统一收尾），\n  // 这样全局 npm 首次失败后可以干净地换参数重试一次。\n  const spawnOnce = (attemptArgs: string[], registry?: string): Promise<InstallResult> => new Promise((resolveOnce) => {\n    let stdout